import { ConsumptionUtil } from "@514labs/moose-lib";

export default async function handler(query: any) {
  const { records } = await ConsumptionUtil.query({
    query: `
      SELECT
        product_id,
        view_count,
        cart_count,
        purchase_count,
        total_revenue
      FROM TopProducts
      ORDER BY purchase_count DESC, total_revenue DESC
    `,
  });

  return {
    status: 200,
    headers: {
      "Content-Type": "application/json",
      "Cache-Control": "public, max-age=30"
    },
    body: JSON.stringify({
      top_products: records
    })
  };
}

