### Build REST API Query with MooseStack

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/apis/semantic-layer.mdx

Implement a REST API endpoint using buildQuery to handle dynamic query parameters and execute ClickHouse queries.

```typescript
import { Api, buildQuery } from "@514labs/moose-lib";
import { visitMetrics } from "../query-layer/visits-model";

interface VisitQueryParams {
  studio_id: number;
  dimensions?: string;
  metrics?: string;
  start_date_gte?: string;
  start_date_lte?: string;
  limit?: number;
}

export default new Api<VisitQueryParams, any>("visits",
  async ({ studio_id, dimensions, metrics, start_date_gte, start_date_lte, limit }, { client }) => {
    const results = await buildQuery(visitMetrics)
      .dimensions(dimensions ? dimensions.split(",") : ["day"])
      .metrics(metrics ? metrics.split(",") : ["totalVisits"])
      .filter("studioId", "eq", studio_id)
      .filter("startDate", "gte", start_date_gte)
      .filter("startDate", "lte", start_date_lte)
      .limit(limit || 100)
      .execute(client.query);

    return results;
  }
);
```

```python
from moose_lib import Api, MooseClient, build_query
from pydantic import BaseModel
from typing import Optional
from app.query_layer.visits_model import visit_metrics

class VisitQueryParams(BaseModel):
    studio_id: int
    dimensions: Optional[str] = None
    metrics: Optional[str] = None
    start_date_gte: Optional[str] = None
    start_date_lte: Optional[str] = None
    limit: Optional[int] = None

def run(client: MooseClient, params: VisitQueryParams) -> list[dict]:
    results = (
        build_query(visit_metrics)
        .dimensions(params.dimensions.split(",") if params.dimensions else ["day"])
        .metrics(params.metrics.split(",") if params.metrics else ["totalVisits"])
        .filter("studioId", "eq", params.studio_id)
        .filter("startDate", "gte", params.start_date_gte)
        .filter("startDate", "lte", params.start_date_lte)
        .limit(params.limit or 100)
        .execute(client.query)
    )
    return results

visits_api = Api[VisitQueryParams, dict](name="visits", query_function=run)
```

--------------------------------

### Define a Custom Consumption API

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/guides/data-warehouses.mdx

Create a TypeScript API definition using the MooseStack library to query warehouse data via SQL.

```typescript
// app/apis/sales_summary.ts

import { Api } from "@514labs/moose-lib";

interface SalesSummaryParams {
  startDate: string;
  endDate: string;
}

interface SalesSummaryResult {
  date: string;
  revenue: number;
  orders: number;
  units: number;
}

export const salesSummaryApi = new Api<SalesSummaryParams, SalesSummaryResult[]>(
  "sales-summary",
  async ({ startDate, endDate }, { client, sql }) => {
    const result = await client.query.execute<SalesSummaryResult>(sql`
      SELECT
        toString(d.date) as date,
        SUM(f.total_amount) as revenue,
        COUNT(DISTINCT f.order_id) as orders,
        SUM(f.quantity) as units
      FROM fact_order_items f
      JOIN dim_date d ON f.order_date_key = d.date_key
      WHERE d.date BETWEEN ${startDate} AND ${endDate}
      GROUP BY d.date
      ORDER BY d.date
    `);

    return result.json();
  }
);
```

```typescript
export * from "./apis/sales_summary";
```

--------------------------------

### Define a Basic API Endpoint in TypeScript

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/apis/analytics-api.mdx

Define an API endpoint with query parameters and a result type. Ensure `SourceTable` is not null using `!`. The `client.query.execute` method is used to run the SQL query.

```typescript
```ts filename="ExampleApi.ts" copy
import { Api } from "@514labs/moose-lib";
import { SourcePipeline } from "path/to/SourcePipeline"; 

// Define the query parameters
interface QueryParams {
  filterField: string;
  maxResults: number;
}

// Model the query result type
interface ResultItem {
  id: number;
  name: string;
  value: number;
}


const SourceTable = SourcePipeline.table!; // Use `!` to assert that the table is not null
const cols = SourceTable.columns;

// Define the result type as an array of the result item type
export const exampleApi = new Api<QueryParams, ResultItem[]>("example_endpoint",  
    async ({ filterField, maxResults }: QueryParams, { client, sql }) => {
        const query = sql.statement`
        SELECT
          ${cols.id},
          ${cols.name},
          ${cols.value}
        FROM ${SourceTable}
        WHERE category = ${filterField}
        LIMIT ${maxResults}`;

        // Set the result type to the type of the each row in the result set
        const resultSet = await client.query.execute<ResultItem>(query);

        // Return the result set as an array of the result item type
        return await resultSet.json();
    });
```
```

```typescript
```ts filename="SourcePipeline.ts" copy
import { IngestPipeline } from "@514libs/moose-lib";

interface SourceSchema {
  id: number;
  name: string;
  value: number;
}

export const SourcePipeline = new IngestPipeline<SourceSchema>("Source", {
  ingestApi: false,
  stream: true,
  table: true,
});
```
```

