import { IngestPipeline, MaterializedView, sql } from "@514labs/moose-lib";

// Product Event Data Model
export interface ProductEvent {
  event_id: string;
  event_ts: Date;
  user_id: string;
  product_id: string;
  event_type: "view" | "cart" | "purchase";
  properties: Record<string, any>;
}

// Ingest Pipeline for Product Events
export const ProductEventPipeline = new IngestPipeline<ProductEvent>("ProductEvent", {
  table: {
    orderByFields: ["event_ts", "user_id", "product_id"]
  },
  stream: true,
  ingestApi: true,
});

// Get table reference
const productEventTable = ProductEventPipeline.table;
if (!productEventTable) {
  throw new Error("ProductEvent table not configured in pipeline");
}

// Aggregated Data Models
export interface TopProducts {
  product_id: string;
  view_count: number;
  cart_count: number;
  purchase_count: number;
  total_revenue: number;
}

export interface ConversionFunnel {
  step: string;
  step_order: number;
  total_events: number;
  unique_users: number;
}

export interface HourlyActivity {
  hour: Date;
  event_type: string;
  event_count: number;
}

// Materialized Views
export const TopProductsMV = new MaterializedView<TopProducts>({
  tableName: "TopProducts",
  materializedViewName: "TopProducts_MV",
  orderByFields: ["purchase_count", "total_revenue"],
  selectTables: [productEventTable],
  selectStatement: sql`
    SELECT
      product_id,
      countIf(event_type = 'view') AS view_count,
      countIf(event_type = 'cart') AS cart_count,
      countIf(event_type = 'purchase') AS purchase_count,
      sumIf(cast(JSONExtractFloat(properties, 'price') AS Float64), event_type = 'purchase') AS total_revenue
    FROM ${productEventTable}
    GROUP BY product_id
  `,
});

export const ConversionFunnelMV = new MaterializedView<ConversionFunnel>({
  tableName: "ConversionFunnel",
  materializedViewName: "ConversionFunnel_MV",
  orderByFields: ["step_order"],
  selectTables: [productEventTable],
  selectStatement: sql`
    SELECT
      'views' AS step,
      1 AS step_order,
      count() AS total_events,
      uniq(user_id) AS unique_users
    FROM ${productEventTable}
    WHERE event_type = 'view'

    UNION ALL

    SELECT
      'carts' AS step,
      2 AS step_order,
      count() AS total_events,
      uniq(user_id) AS unique_users
    FROM ${productEventTable}
    WHERE event_type = 'cart'

    UNION ALL

    SELECT
      'purchases' AS step,
      3 AS step_order,
      count() AS total_events,
      uniq(user_id) AS unique_users
    FROM ${productEventTable}
    WHERE event_type = 'purchase'
  `,
});

export const HourlyActivityMV = new MaterializedView<HourlyActivity>({
  tableName: "HourlyActivity",
  materializedViewName: "HourlyActivity_MV",
  orderByFields: ["hour", "event_type"],
  selectTables: [productEventTable],
  selectStatement: sql`
    SELECT
      toStartOfHour(event_ts) AS hour,
      event_type,
      count() AS event_count
    FROM ${productEventTable}
    GROUP BY hour, event_type
  `,
});

// Export APIs
export { topProductsApi } from "./apis/top-products";
export { conversionFunnelApi } from "./apis/conversion-funnel";
export { hourlyActivityApi } from "./apis/hourly-activity";

