  materializedViewName: "ConversionFunnel_MV",
  orderByFields: ["step_order"],
  selectTables: [productEventTable],
  selectStatement: sql`
    SELECT
      'views' AS step,
      1 AS step_order,
      count() AS total_events,
      uniq(user_id) AS unique_users
    FROM ${productEventTable}
    WHERE event_type = 'view'

    UNION ALL

    SELECT
      'carts' AS step,
      2 AS step_order,
      count() AS total_events,
      uniq(user_id) AS unique_users
    FROM ${productEventTable}
    WHERE event_type = 'cart'

    UNION ALL

    SELECT
      'purchases' AS step,
      3 AS step_order,
      count() AS total_events,
      uniq(user_id) AS unique_users
    FROM ${productEventTable}
    WHERE event_type = 'purchase'
  `,
});

export const HourlyActivityMV = new MaterializedView<HourlyActivity>({
  tableName: "HourlyActivity",
  materializedViewName: "HourlyActivity_MV",
  orderByFields: ["hour", "event_type"],
  selectTables: [productEventTable],
  selectStatement: sql`
    SELECT
      toStartOfHour(event_ts) AS hour,
      event_type,
      count() AS event_count
    FROM ${productEventTable}
    GROUP BY hour, event_type
  `,
});

